{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Safinamide, a close analogue with a basic benzylamine and amide, had absolute oral bioavailability of 95% in fasted healthy subjects after a 50 mg IR tablet, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tegoprazan, a benzimidazole-containing oral drug structurally similar to the query's benzimidazole/lactam core, showed estimated oral bioavailability of 86–100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide, an imide/lactam-type small molecule, showed probably high absolute oral bioavailability of 80–100% at low doses in fasting volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, a lactam-containing small molecule, was completely absorbed orally with absolute bioavailability of 73 ± 25% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Aprepitant, a moderately lipophilic oral drug with amide and fluorophenyl motifs, had oral bioavailability of about 59% for the 125 mg capsule, supporting F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Irbesartan, an oral drug with a cyclic amide and acidic tetrazole, had absolute bioavailability of 61 ± 10% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental analogues show high absolute oral bioavailability (52–100%), including structurally similar benzimidazole-containing tegoprazan and safinamide; no evidence supports F < 20%. Therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct pharmacokinetic measurement exists for the query molecule.",
    "The query's fused lactam-benzimidazole scaffold is not exactly represented by any evidence molecule, so absorption and first-pass effects could differ.",
    "No retrieved evidence molecule had low oral bioavailability, limiting contrast for the F >= 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

